// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(uint256 ts, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);
        uint256 warpTime = bound(ts, 1_000_000, 2_000_000_000);
        vm.warp(warpTime);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(ts);
        (uint unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime >= warpTime, "unlockTime must be clamped to at least block.timestamp");
    }
}
